bad.code:
queue.on('message', async msg => {
  await msg.ack()                          // lost if we crash below
  await sendReceiptEmail(msg.body.orderId) // runs again on redelivery
})

good.code:
queue.on('message', async msg => {
  const fresh = await db.tx(async tx => {
    const inserted = await tx.query(
      'INSERT INTO processed (msg_id) VALUES ($1) ON CONFLICT DO NOTHING RETURNING 1',
      [msg.id])
    if (!inserted.rowCount) return false
    await tx.query('INSERT INTO receipts (order_id) VALUES ($1)', [msg.body.orderId])
    return true
  })
  if (fresh) await emailOutbox.enqueue(msg.body.orderId) // email sent by its own idempotent job
  await msg.ack()
})

await db.tx(async tx => {
  await tx.orders.insert(order)
  await tx.outbox.insert({ id: uuid(), topic: 'order-placed', payload: order })
})
// relay: SELECT unsent rows in order -> publish -> mark sent

better.code:
await producer.send({
  topic: 'order-events',
  key: order.id,            // same key -> same partition -> same consumer
  value: { type: 'paid', version: order.version }
})
// consumer also ignores events with version <= stored version
